const Wrapper = styled.div`
    width:100%;
    height:100%;
    position: fixed;
    top: 0;
    left: 0;
    z-index: 1000;
    height:100vh;
    overflow: hidden;
    img {
        cursor: pointer;
    }
`;

const Container = styled.div`
    max-width:512px;
    width:50%;
    height:380px;
    background-color: ${({ theme }) => theme.color.bg};
    padding:0 2rem;
    display:flex;
    flex-direction:column;
    justify-content:center;
    position: fixed;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    @media screen and (max-width : 768px ){
        width:90%;
    }
`;

const TitleWrapper = styled.div`
    display:flex;
    justify-content:space-between;
    align-items:center;
    margin-bottom:2rem;
`;

const Title = styled.div`
    display:flex;
    align-items:center;
    gap:1rem;
    img {
        display:none;
    }
`;

const WalletWrapper = styled.div`
    display:flex;
    flex-direction:column;
    gap:1rem;
`;

const WalletList = styled.div`
    display:flex;
    align-items:center;
    justify-content:space-between;
    gap:1rem;
    padding: 1rem 1.5rem;
    background: rgba(255, 255, 255, 0.05);
`;

const WalletItem = styled.div`
    display:flex;
    align-items:center;
    gap:1rem;
    @media screen and (max-width : 576px ){
        button { display:none; }
    }    
`;

const ButtonWrapper = styled.div`
    display:flex;
    justify-content:center;
    margin-top:2rem;
`;

export default function ConnectModal({ setIsConnectModalOpen }: { setIsConnectModalOpen: (isConnectModalOpen: boolean) => void }) {
    const { isMobile } = useContext(WindowContext);
    const [isOpen, setIsOpen] = useState(false);
    return (
        <Wrapper className="bg-modal">
            <Container>
                <TitleWrapper>
                    <Title>
                        <h5>Connect Wallet</h5>
                        <img src={`${process.env.PUBLIC_URL}/assets/images/icon/explanation.png`} alt="close" />
                    </Title>
                    {!isMobile && <img
                        src={theme.icon.close} alt="close" onClick={() => setIsConnectModalOpen(false)}
                    />}
                </TitleWrapper>
                <WalletWrapper>
                    <PhanthomWallet />
                    <OKXWallet />
                    <WalletList onClick={() => { setIsOpen(true) }}>
                        <WalletItem>
                            <img src={theme.icon.metamask} alt="metamask" />
                            <p className="text-gray">MetaMask</p>
                        </WalletItem>
                        <WalletItem >
                            <ButtonMedium bgColor="#08080829" textColor={theme.color.mainGreen} borderColor="none" disabled className="disabled text-gray" >
                                <span>NOT INSTALLED</span>
                            </ButtonMedium>
                            <img src={theme.icon.rightArrow} alt="right-arrow" />
                        </WalletItem>
                    </WalletList>
                </WalletWrapper>
                {
                    isMobile && (
                        <ButtonWrapper>
                            <Button onClick={() => setIsConnectModalOpen(false)}>Close</Button>
                        </ButtonWrapper>
                    )
                }
            </Container>
            <MessageModal title="Comming Soon" content="Currently being prepared" action="prepare" isOpen={isOpen} setIsOpen={setIsOpen} />
        </Wrapper>
    )
}