import { useRef, useEffect } from 'react';
import { SignalChartOptions } from '../../utils/chart/signalChartOptions';
import { candleData, signalData } from '../../types/chart';
export default function SignalChart({candleData,signalData}:{candleData:candleData,signalData:signalData[]}) {
    const chartInstance = new SignalChartOptions();
    const chartContainerRef = useRef<HTMLDivElement>(null);
    useEffect(()=>{
        if(chartContainerRef.current){
            const chart = chartInstance.createChart(chartContainerRef.current);
            const candlestickSeries = chartInstance.createSeries(chart,'candle','candleOptions');
            const pinkSeries = chartInstance.createSeries(chart,'line','pinkOptions');
            const aoSeries = chartInstance.createSeries(chart,'baseLine','aoSeriesOptions');
            if(candleData){
                candlestickSeries.setData(candleData.candleData);
                aoSeries.setData(candleData.aoData);
            }
            
            if(signalData){
                candlestickSeries.setMarkers(signalData);
            }
            return ()=>{
                if(chart){
                    chart.remove();
                }
            }
        }
    },[candleData,signalData]);
    
    return (
        <div
            ref={chartContainerRef}
        >
        </div>
    );
}