export const DateUtil = new class {
    localTimezone: string;
    
    constructor() {
        this.localTimezone = Intl.DateTimeFormat().resolvedOptions().timeZone;
    }
    convertDate(date: string){ // scorechart 사용(날짜 => 타임스탬프)
        return new Date(date).getTime()
    }
    convertTimeScale(timeStamp: number){
        // console.log('timeStamp',timeStamp);
        
        var convertTime = new Date(timeStamp*1000);
        
        var optionsT: Intl.DateTimeFormatOptions = {
            // year: 'numeric',
            month: '2-digit',
            day: '2-digit',
            hour: '2-digit',
            minute:"2-digit",
            hour12: false,
            timeZone: this.localTimezone,
        };
        var localTime = convertTime.toLocaleString('en-US', optionsT).replace(',', ''); // 쉼표(,) 제거
        localTime = localTime.replace(/\//g, '-'); // "/"를 "-"로 대체
        // console.log('localTime',localTime,this.localTimezone);
        
        return localTime;
    }
    convertTimeScaleWithLocal(originalTime: number, timeZone: string){
        // 먼저 타임스탬프를 Date 객체로 변환
        let date = new Date(new Date(originalTime * 1000).toLocaleString('en-US', { timeZone }));
        
        const year = date.getFullYear();
        const month = (date.getMonth() + 1).toString().padStart(2, '0');
        const day = date.getDate().toString().padStart(2, '0');
        const hours = date.getHours().toString().padStart(2, '0');
        const minutes = date.getMinutes().toString().padStart(2, '0');
        
        var formattedDateTime = `${year}-${month}-${day} ${hours}:${minutes}`;
        
        return formattedDateTime;
    }
    convertCurrentHour(timeStamp: string){
        let targetTime = new Date(this.convertDate(timeStamp));
        var day = targetTime.getDate().toString().padStart(2, '0') //일 2자리 (01, 02 ... 31)
        var hour = ("0" + targetTime.getHours()).slice(-2);
        return day+hour
    }
}