export default function AITradingProfit() {
    const { isMobile } = useContext(WindowContext);
    const navigate = useNavigate();
    const { data: profitData, isLoading: profitLoading, error: profitError } = useChartFetchAPI(
        '/sigx/pnl_history',
        ['pnlHistory'],
        {
            enabled: true,
        }
    );
    // console.log('profitData', profitData);
    const downLoadHistory = () => {
        fetch(`${process.env.REACT_APP_CHART_URL}/sigx/pnl_history_download`, {
            method: 'GET',
            headers: {
                'Content-Type': 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
            },
        })
            .then(response => response.blob())
            .then(blob => {
                const url = window.URL.createObjectURL(new Blob([blob]));
                const a = document.createElement('a');
                a.href = url;
                a.download = 'ai_trading_history.xlsx';
                a.click();
            })
            .catch(error => {
                console.error('Error downloading history:', error);
            });
    }
    return (
        <Wrapper>
            <Container>
                <TitleWrapper>
                    <h1>AI trading Profit</h1>
                    <h4 className="text-gray">
                        For 1month
                        <span className={colorFormat(Number(profitData?.month_profit))}>
                            {" " + percentFormat(Number(profitData?.month_profit))}
                        </span>
                    </h4>
                </TitleWrapper>
                <ProfitContainer>
                    <ProfitList className="header">
                        <p className="mb">Date</p>
                        <p>Signal</p>
                        <p>Buy</p>
                        <p>Sell</p>
                        <p>Profit(%)</p>
                    </ProfitList>
                    {
                        !isMobile ? (
                            <>
                                {
                                    profitData?.results?.map((item: any) => (
                                        <ProfitList className="bg-blur" onClick={() => navigate(`/ai-chart/${item.symbol}USDT`)}>
                                            <p>{getDateStr(item.datetime)}</p>
                                            <div className="symbol-wrapper">                                                {item.signal === 'L' ? <LSignal /> : <SSignal />}</div>
                                            <div className="symbol-wrapper">
                                                <p>{item.symbol} ${item.buy_price}</p>
                                            </div>
                                            <div className="symbol-wrapper">
                                                <p>{item.symbol} ${item.sell_price}</p>
                                            </div>
                                            <p className={colorFormat(Number(item.profit))}>{percentFormat(Number(item.profit))}</p>
                                        </ProfitList>
                                    ))
                                }
                            </>
                        ) : (
                            <>
                                {
                                    profitData?.results?.map((item: any) => (
                                        <ProfitContainerMb className="bg-blur">
                                            <ProfitListMb className="header">
                                                <p>{getHourStr(item.datetime)} {item.symbol}</p>
                                                <p></p>
                                                <p></p>
                                                <Link to={`/ai-chart/${item.symbol}USDT`}>
                                                    <img src={theme.icon.chart} alt="chart" className="chart-icon" />
                                                </Link>
                                            </ProfitListMb>
                                            <ProfitListMb>
                                                <div className="symbol-wrapper">
                                                    {item.signal === 'L' ? <LSignal /> : <SSignal />}
                                                </div>
                                                <div className="symbol-wrapper">
                                                    <p>${item.buy_price}</p>
                                                </div>
                                                <div className="symbol-wrapper">
                                                    <p>${item.sell_price}</p>
                                                </div>
                                                <p className={colorFormat(Number(item.profit))}>{percentFormat(Number(item.profit))}</p>
                                            </ProfitListMb>
                                        </ProfitContainerMb>
                                    ))
                                }
                            </>
                        )
                    }
                    <ButtonWrapper>
                        <Button onClick={() => downLoadHistory()}>View History</Button>
                    </ButtonWrapper>
                </ProfitContainer>
            </Container>
        </Wrapper>
    );
}